begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claim.role','authenticated',true);
create function pg_temp.identity_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.identity_denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpected permission %',label;end$$;
grant execute on all functions in schema pg_temp to authenticated,anon;
select pg_temp.identity_ok((select not enabled from app_feature_flags where key='personal_username_accounts'),'username accounts disabled by default');
insert into auth.users(id,email) values('ac100000-0000-0000-0000-000000000001','persona.uno@login.hemocura.invalid'),('ac100000-0000-0000-0000-000000000002','persona.dos@login.hemocura.invalid');
insert into profiles(id,full_name,active) values('ac100000-0000-0000-0000-000000000001','Persona ficticia 1',true),('ac100000-0000-0000-0000-000000000002','Persona ficticia 2',true);
insert into user_account_contacts(user_id,username,contact_email,created_by) values('ac100000-0000-0000-0000-000000000001','persona.uno','equipo@example.invalid','f9200000-0000-0000-0000-000000000001'),('ac100000-0000-0000-0000-000000000002','persona.dos','equipo@example.invalid','f9200000-0000-0000-0000-000000000001');
select pg_temp.identity_ok((select count(*)=2 and count(distinct contact_email)=1 from user_account_contacts),'two personal accounts share contact email');
select pg_temp.identity_denied($q$update user_account_contacts set username='persona.uno' where username='persona.dos'$q$,'duplicate username is rejected');
select pg_temp.identity_denied($q$update user_account_contacts set username='PERSONA.DOS' where username='persona.dos'$q$,'noncanonical username rejected');
set local role authenticated;select set_config('request.jwt.claim.sub','ac100000-0000-0000-0000-000000000001',true);
select pg_temp.identity_ok((select count(*)=1 and bool_and(user_id=auth.uid()) from user_account_contacts),'personal contact read excludes colleague with shared email');
select pg_temp.identity_ok(not has_permission('ACCESS_ADMIN') and not has_permission('HYPERBARIC_SESSION_WRITE'),'shared contact grants no role or clinical permission');
select pg_temp.identity_denied($q$update user_account_contacts set username='otro.usuario' where user_id=auth.uid()$q$,'browser cannot change account identifier');
select pg_temp.identity_denied($q$insert into user_account_contacts values(auth.uid(),'otro.usuario',null,now(),auth.uid())$q$,'browser cannot provision identities');
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select pg_temp.identity_ok((select count(*)=2 from user_account_contacts),'actual super user can inspect both accounts');
reset role;set local role anon;
select pg_temp.identity_denied($q$select * from user_account_contacts$q$,'anonymous cannot enumerate usernames or contacts');
rollback;
